fast_pseudocode:
# With @triton.autotune exploring XBLOCK and num_warps
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 128}, num_warps=4),
        triton.Config({'XBLOCK': 256}, num_warps=4),
        triton.Config({'XBLOCK': 512}, num_warps=8),
        triton.Config({'XBLOCK': 1024}, num_warps=8),
    ],
    key=['xnumel']
)
@triton.jit
def kernel(...):
    XBLOCK: tl.constexpr  # now autotuned
    # 32 blocks, 64 threads/block, 110 regs/thread
    # 40.03us, 720K instructions
